PRAGMA application_id=1128548401;
PRAGMA user_version=20;
BEGIN TRANSACTION;
CREATE TABLE history_identity(
 project_id TEXT PRIMARY KEY, next_source_sequence INTEGER NOT NULL,
 next_delivery_sequence INTEGER NOT NULL);
INSERT INTO "history_identity" VALUES('prj_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',1,1);
CREATE TABLE project_account_settlements(
 project_id TEXT NOT NULL,run_handle TEXT NOT NULL,attempt INTEGER NOT NULL,claim_id TEXT,
 release_kind TEXT NOT NULL CHECK(release_kind IN ('lost','crashed','released_unacknowledged')),
 closure BLOB NOT NULL,settled_at_ms INTEGER NOT NULL,
 PRIMARY KEY(project_id,run_handle,attempt),UNIQUE(project_id,claim_id),
 FOREIGN KEY(project_id) REFERENCES history_identity(project_id));
CREATE TABLE project_cleanup_acknowledgements(
 project_id TEXT NOT NULL,run_handle TEXT NOT NULL,attempt INTEGER NOT NULL,
 receipt BLOB NOT NULL,ack_digest TEXT NOT NULL,journal_seal TEXT NOT NULL,
 PRIMARY KEY(project_id,run_handle,attempt),
 FOREIGN KEY(project_id,run_handle,attempt) REFERENCES project_cleanup_receipts(project_id,run_handle,attempt));
CREATE TABLE project_cleanup_receipts(
 project_id TEXT NOT NULL,run_handle TEXT NOT NULL,attempt INTEGER NOT NULL,
 claim_id TEXT NOT NULL,evidence BLOB NOT NULL,cleanup_digest TEXT NOT NULL,journal_seal TEXT NOT NULL,
 PRIMARY KEY(project_id,run_handle,attempt),UNIQUE(project_id,claim_id),
 FOREIGN KEY(project_id,run_handle,attempt) REFERENCES project_cleanup_reservations(project_id,run_handle,attempt));
CREATE TABLE project_cleanup_reservations(
 project_id TEXT NOT NULL,run_handle TEXT NOT NULL,attempt INTEGER NOT NULL,
 binding BLOB NOT NULL,lease_digest TEXT NOT NULL,reservation_digest TEXT NOT NULL,
 cleanup_digest TEXT,state_digest TEXT NOT NULL, account_release_digest TEXT,
 PRIMARY KEY(project_id,run_handle,attempt),UNIQUE(project_id,reservation_digest),
 FOREIGN KEY(project_id,run_handle,attempt) REFERENCES result_leases(project_id,run_handle,attempt));
CREATE TABLE project_execution_consumptions(
 project_id TEXT NOT NULL, claim_id TEXT NOT NULL, registration_digest TEXT NOT NULL,
 grant BLOB NOT NULL, consumed_at_ms INTEGER NOT NULL,
 PRIMARY KEY(project_id,claim_id), UNIQUE(project_id,registration_digest),
 FOREIGN KEY(project_id,claim_id) REFERENCES result_reservations(project_id,claim_id));
CREATE TABLE project_holds(
 project_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('driver_entry','preparation','lease','reservation','orchestration','open_binding','result_custody')),
 identity TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('held','releasing','released')),
 generation INTEGER NOT NULL DEFAULT 1 CHECK(generation>=1),
 instance TEXT,lease_case TEXT CHECK(lease_case IN ('unarmed','armed','closing_denied','admitted_unbound')),
 taken_at_ms INTEGER NOT NULL,due_at_ms INTEGER,next_check_ms INTEGER NOT NULL DEFAULT 0,
 released_at_ms INTEGER,release_kind TEXT,request_id TEXT,request_digest TEXT,receipt TEXT,evidence TEXT,
 CHECK((kind='lease')=(lease_case IS NOT NULL)),
 CHECK((kind IN ('driver_entry','preparation'))=(instance IS NOT NULL)),
 CHECK(state='released' OR released_at_ms IS NULL),
 CHECK(state<>'released' OR release_kind IS NOT NULL),
 CHECK(release_kind IS NULL OR (kind='lease' AND release_kind IN ('withdrawn_unsent','denied','fenced','bound','lost_unbound')) OR (kind='reservation' AND release_kind IN ('completed','lost','crashed','released_unacknowledged')) OR (kind='driver_entry' AND release_kind IN ('retired','handed_over','service_stopped')) OR (kind='preparation' AND release_kind IN ('retired','submit_refused','never_launch_local','service_stopped')) OR (kind='orchestration' AND release_kind IN ('closed','interrupted_unattended')) OR (kind='open_binding' AND release_kind IN ('withdrawn','claimed','fenced','account_final')) OR (kind='result_custody' AND release_kind IN ('lost_with_reservation','retention','orchestration_closed'))),
 PRIMARY KEY(project_id,kind,identity),
 FOREIGN KEY(project_id) REFERENCES history_identity(project_id));
INSERT INTO "project_holds" VALUES('prj_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','orchestration','orc_a907e1a7b779d666b509db122d618231ad710dfa36485ffd','released',1,NULL,NULL,1000,NULL,0,1500,'closed',NULL,NULL,'466201d5ed8b7a8c0e183526165609fa9331176b1e082d9daddc906956545a6c','{"ended_by_update_unrecorded":false}');
CREATE TABLE project_host_opens(
 project_id TEXT NOT NULL,run_handle TEXT NOT NULL,attempt INTEGER NOT NULL,
 binding BLOB NOT NULL,record_id TEXT NOT NULL,record_content_digest TEXT NOT NULL,
 source_sequence INTEGER NOT NULL,ingested_at_ms INTEGER NOT NULL,
 late INTEGER NOT NULL CHECK(late IN (0,1)),journal_seal TEXT NOT NULL,
 PRIMARY KEY(project_id,run_handle,attempt),UNIQUE(project_id,record_id),
 FOREIGN KEY(project_id,run_handle,attempt) REFERENCES result_leases(project_id,run_handle,attempt),
 FOREIGN KEY(project_id,record_id) REFERENCES records(project_id,record_id));
CREATE TABLE project_learning_activation(
 project_id TEXT NOT NULL PRIMARY KEY,import_id TEXT,source_identity_digest TEXT,
 records_manifest_digest TEXT,qa_manifest_digest TEXT,record_count INTEGER NOT NULL,
 qa_count INTEGER NOT NULL,live_sequence INTEGER NOT NULL,activated_at_ms INTEGER NOT NULL,
 activation_seal TEXT NOT NULL,
 FOREIGN KEY(project_id) REFERENCES history_identity(project_id));
CREATE TABLE project_learning_attestations(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,subject_record_id TEXT NOT NULL,
 signature BLOB NOT NULL,signature_digest TEXT NOT NULL,observed_at_ms INTEGER NOT NULL,
 PRIMARY KEY(project_id,import_id,subject_record_id),
 FOREIGN KEY(project_id,import_id,subject_record_id) REFERENCES project_learning_records(project_id,import_id,record_id));
CREATE TABLE project_learning_chunk_memberships(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,chunk_index INTEGER NOT NULL,
 chunk_digest TEXT NOT NULL,membership BLOB NOT NULL,membership_digest TEXT NOT NULL,
 PRIMARY KEY(project_id,import_id,chunk_index),
 FOREIGN KEY(project_id,import_id,chunk_index)
 REFERENCES project_learning_import_chunks(project_id,import_id,chunk_index));
CREATE TABLE project_learning_import_chunks(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,chunk_index INTEGER NOT NULL,
 chunk_digest TEXT NOT NULL,receipt BLOB NOT NULL,
 PRIMARY KEY(project_id,import_id,chunk_index),
 FOREIGN KEY(project_id,import_id) REFERENCES project_learning_imports(project_id,import_id));
CREATE TABLE project_learning_imports(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,manifest_digest TEXT NOT NULL,manifest BLOB NOT NULL,
 next_chunk INTEGER NOT NULL,record_count INTEGER NOT NULL,attestation_count INTEGER NOT NULL,
 total_bytes INTEGER NOT NULL,last_source_sequence INTEGER NOT NULL,chain_digest TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('staging','staged')),created_at_ms INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL,
 PRIMARY KEY(project_id,import_id),FOREIGN KEY(project_id) REFERENCES history_identity(project_id));
CREATE TABLE project_learning_qa_chunks(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,chunk_index INTEGER NOT NULL,
 chunk_digest TEXT NOT NULL,receipt BLOB NOT NULL,
 PRIMARY KEY(project_id,import_id,chunk_index),
 FOREIGN KEY(project_id,import_id) REFERENCES project_learning_qa_imports(project_id,import_id));
CREATE TABLE project_learning_qa_imports(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,manifest_digest TEXT NOT NULL,manifest BLOB NOT NULL,
 next_chunk INTEGER NOT NULL,qa_count INTEGER NOT NULL,total_bytes INTEGER NOT NULL,
 last_qa_id TEXT NOT NULL,chain_digest TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('staging','staged')),
 created_at_ms INTEGER NOT NULL,updated_at_ms INTEGER NOT NULL,
 PRIMARY KEY(project_id,import_id),
 FOREIGN KEY(project_id,import_id) REFERENCES project_learning_imports(project_id,import_id));
CREATE TABLE project_learning_qa_records(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,qa_id TEXT NOT NULL,qa_digest TEXT NOT NULL,
 host_outcome_digest TEXT NOT NULL,verifier_host_outcome_digest TEXT NOT NULL,
 accepted INTEGER NOT NULL CHECK(accepted IN (0,1)),observed_at_ms INTEGER NOT NULL,content BLOB NOT NULL,
 PRIMARY KEY(project_id,import_id,qa_id),UNIQUE(project_id,import_id,host_outcome_digest),
 UNIQUE(project_id,import_id,qa_digest),
 FOREIGN KEY(project_id,import_id) REFERENCES project_learning_qa_imports(project_id,import_id));
CREATE TABLE project_learning_records(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,record_id TEXT NOT NULL,record_type TEXT NOT NULL,
 source TEXT NOT NULL,source_sequence INTEGER NOT NULL,observed_at_ms INTEGER NOT NULL,
 ingested_at_ms INTEGER NOT NULL,expires_at_ms INTEGER,late INTEGER NOT NULL CHECK(late IN (0,1)),
 content BLOB NOT NULL,content_digest TEXT NOT NULL,
 PRIMARY KEY(project_id,import_id,record_id),UNIQUE(project_id,import_id,source_sequence),
 FOREIGN KEY(project_id,import_id) REFERENCES project_learning_imports(project_id,import_id));
CREATE TABLE project_learning_source_chunks(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,chunk_index INTEGER NOT NULL,
 content BLOB NOT NULL,content_digest TEXT NOT NULL,
 PRIMARY KEY(project_id,import_id,chunk_index),
 FOREIGN KEY(project_id,import_id) REFERENCES project_learning_source_images(project_id,import_id));
CREATE TABLE project_learning_source_images(
 project_id TEXT NOT NULL,import_id TEXT NOT NULL,metadata BLOB NOT NULL,
 next_chunk INTEGER NOT NULL,total_bytes INTEGER NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('staging','staged')),
 PRIMARY KEY(project_id,import_id),
 FOREIGN KEY(project_id,import_id) REFERENCES project_learning_imports(project_id,import_id));
CREATE TABLE project_operational_qa(
 project_id TEXT NOT NULL,worker_outcome_digest TEXT NOT NULL,verifier_outcome_digest TEXT NOT NULL,
 worker_admission_digest TEXT NOT NULL,verifier_admission_digest TEXT NOT NULL,
 check_receipt_id TEXT NOT NULL,scope_digest TEXT NOT NULL,qa_digest TEXT NOT NULL,qa BLOB NOT NULL,
 outcome_record_id TEXT NOT NULL,outcome_digest TEXT NOT NULL,source_sequence INTEGER NOT NULL,
 ingested_at_ms INTEGER NOT NULL,late INTEGER NOT NULL CHECK(late IN (0,1)),
 consumed_at_ms INTEGER NOT NULL,record_seal TEXT NOT NULL,
 PRIMARY KEY(project_id,worker_outcome_digest),UNIQUE(project_id,check_receipt_id),
 UNIQUE(project_id,outcome_record_id),FOREIGN KEY(project_id) REFERENCES history_identity(project_id));
CREATE TABLE project_orchestration_checkpoints(
 project_id TEXT NOT NULL,orchestration_handle TEXT NOT NULL,sequence INTEGER NOT NULL,
 content BLOB NOT NULL,checkpoint_digest TEXT NOT NULL,
 PRIMARY KEY(project_id,orchestration_handle,sequence),
 FOREIGN KEY(project_id,orchestration_handle) REFERENCES project_orchestrations(project_id,orchestration_handle));
